    """True when in low-interactivity mode — go full speed, no mercy."""
    return _usage_state["over_budget_today"] or _usage_state["mode"] == "low_interactivity"


def _get_throttle_delay() -> float:
    """Min seconds between forwarded requests.
    Returns 0 when in full-burst (low-interactive) mode."""
    if _is_full_burst():
        return 0.0
    used = _usage_state["used_pct"]
    if used < 50:
        return 0.0
    elif used < 70:
        return 5.0
    elif used < 85:
        return 30.0
    elif used < 95:
        return 120.0
    else:
        return 999999.0  # effectively pause


def _get_max_retries() -> int:
    """Infinite retries when in low-interactive (full burst), 3 otherwise."""
    if _is_full_burst():
