fixed:
def pending_fields(inventory: dict) -> list:
    """Fields that still need an answer (empty value / nothing selected).

    Excludes file-upload and button-like controls (handled separately) and
    already-filled fields, so the LLM only sees what still needs answering on
    this step — never re-answers fields it (or a previous step) filled.

    RULE: when the form marks ANY field required, optional fields are
    deliberately left empty — they never block submission and answering them
    wastes steps. Forms that mark nothing at all fall back to treating every
    visible field as answerable.
    Never raises.
    """
    _all = inventory.get('fields') or []
    any_required = any(f.get('required') for f in _all)
    out = []
    for f in _all:
        if any_required and not f.get('required'):
            continue
        try:
            ftype = (f.get('type') or '').strip().lower()
        except Exception:
            ftype = ''
        if ftype in _SKIP_TYPES:
            continue
        if f.get('tag') == 'group':
            opts = f.get('options') or []
            if not any(bool(o.get('checked')) for o in opts):
                out.append(f)
        else:
            val = str(f.get('value') or '').strip()
            if not val:
                out.append(f)
    return out

