window.__autoAcceptStart = function(config) {
    const state = window.__autoAcceptFreeState;
    if (state.isRunning) window.__autoAcceptStop();

    state.isRunning = true;
    state.sessionID++;

     log('Starting v1.6.0...');

    // Coalesce rapid mutations into at most one scan per DEBOUNCE_MS.
    // This prevents the full-document walk from pegging the main thread
    // on chat/agent output streams.
    const DEBOUNCE_MS = 500;
    let timer = null;
    const runCycle = () => {
        if (!state.isRunning) return;
        if (!hasPromptFast()) return;   // cheap gate: nothing to click
        clickAcceptButtons();
    };
    const schedule = () => {
        if (timer) return;
        timer = setTimeout(() => {
            timer = null;
            runCycle();
        }, DEBOUNCE_MS);
    };

    try {
        const observer = new MutationObserver(schedule);
        observer.observe(document.body || document.documentElement, {
            childList: true,
            subtree: true,
            attributes: true
        });
        state.domObserver = observer;
    } catch (e) { }

    state.clickInterval = setInterval(runCycle, 500);
};

