// Cheap fast-path: only do the expensive full-document walk when an
// ACTIONABLE permission prompt is actually present. Generic notifications
// (monaco-list-row role=dialog for "Install"/"Instructions") and the always-
// present agent side-panel are NOT prompts, so we discriminate by reading
// the container text for PERMISSION_PROMPT_MARKERS. This keeps CPU ~0% when
// idle while still catching real allow/proceed prompts.
const PROMPT_CONTAINER_SELECTOR = '[role="dialog"], .monaco-dialog-box, .monaco-dialog-modal-block, .chat-tool-call, .chat-tool-response, [data-testid*="tool-call"], .antigravity-agent-side-panel, .agent-step, .approval-prompt, [class*="permission"], [class*="approval"], [class*="review"]';
const hasPromptFast = () => {
    try {
        const containers = document.body
            ? document.body.querySelectorAll(PROMPT_CONTAINER_SELECTOR)
            : [];
        for (const c of containers) {
            if (c.offsetParent === null && c.getClientRects().length === 0) continue;
            const txt = getActionText(c);
            if (!txt) continue;
            if (PERMISSION_PROMPT_MARKERS.some(m => txt.includes(m))) return true;
        }
        return false;
    } catch (e) {
        return false;
    }
};

