const PROMPT_CONTAINER_SELECTOR = '[role="dialog"], .monaco-dialog-box, .monaco-dialog-modal-block, .approval-prompt, [class*="approval"], [class*="permission"]';
const PERMISSION_QUESTION_RE = /^\s*(allow|approve|grant|authorize|proceed|accept)\b[^\n]{1,120}\?\s*$/i;
// A REAL "Allow <action>?" prompt renders as an ACTIVE radio group with
// option labels ("Yes, allow this time" / "Yes, and always allow …").
// Historical chat text has no live radiogroup, so gating ONLY on a visible,
// permission-labeled radio group is unambiguous and can never re-spin on
// conversation history. This is cheap (a handful of radio groups at most).
const hasPermissionQuestion = () => {
    try {
        const groups = document.body ? document.body.querySelectorAll('[role="radiogroup"], [class*="radiogroup"], input[type="radio"]') : [];
        for (const g of groups) {
            const group = (g.tagName === 'INPUT') ? (g.closest('[role="radiogroup"], [class*="radiogroup"]') || g) : g;
            if (group.offsetParent === null && group.getClientRects().length === 0) continue;
            const txt = (group.innerText || group.textContent || '').replace(/\s+/g, ' ').trim();
            if (!txt || txt.length > 400) continue;
            const permQ = PERMISSION_QUESTION_RE.test(txt) ||
                          /allow|permission|approve|access|proceed|grant/iu.test(txt);
            const hasChoice = /allow\s*this\s*time|always\s*allow|always\s*proceed|allow\s*once/i.test(txt);
            if (permQ && hasChoice) return true;
        }
        return false;
    } catch (e) {
        return false;
    }
};

