def solve_img(img, question, min_conf=0.5, fourth_thresh=0.55):
    m = get_model()
    tcls = target_class(question)
    target_name = m.names.get(tcls, "unknown") if tcls is not None else "unknown"
    if tcls is None:
        return [], None, target_name, {}
    confs = classify_tiles(img, tcls)
    # Select every tile whose target confidence passes the threshold.
    # reCAPTCHA 3x3 selection grids contain a varying number of matches (1/3/9);
    # confidence threshold is more correct than a fixed top-N.
    answers = sorted([c for c, conf in confs.items() if conf >= min_conf])
    # If nothing passes (rare/edge), fall back to top-3 ranking
    if not answers:
        ranked = sorted(confs.items(), key=lambda kv: -kv[1])
        answers = [c for c, _ in ranked[:3]]
        if len(ranked) >= 4 and ranked[3][1] >= fourth_thresh:
            answers.append(ranked[3][0])
        answers = sorted(answers)
    return answers, tcls, target_name, confs

