// Simple test runner for environments without mocha/jest installed.
let beforeEachFns = [];
let afterEachFns = [];
function describe(name, fn) {
  console.log(`\n${name}`);
  fn();
}
function beforeEach(fn) {
  beforeEachFns.push(fn);
}
function afterEach(fn) {
  afterEachFns.push(fn);
}
function it(name, fn) {
  try {
    for (const b of beforeEachFns) b();
    fn();
    for (const a of afterEachFns) a();
    console.log(`  ✓ ${name}`);
  } catch (err) {
    for (const a of afterEachFns) a();
    console.error(`  ✗ ${name}`);
    console.error(`    ${err.message}`);
    process.exitCode = 1;
  }
}

