// Simple test runner for environments without mocha/jest installed.
var beforeEachFns = [];
var afterEachFns = [];
function describe(name, fn) {
  console.log(`\n${name}`);
  fn();
}
function beforeEach(fn) {
  beforeEachFns.push(fn);
}
function afterEach(fn) {
  afterEachFns.push(fn);
}
function it(name, fn) {
  const done = (err) => {
    if (err) {
      for (const a of afterEachFns) a();
      console.error(`  ✗ ${name}`);
      console.error(`    ${err.message}`);
      process.exitCode = 1;
      return;
    }
    for (const a of afterEachFns) a();
    console.log(`  ✓ ${name}`);
  };
  try {
    if (fn.length > 0) {
      fn((err) => done(err));
      return;
    }
    const result = fn();
    if (result && typeof result.then === 'function') {
      result.then(() => done(), done);
      return;
    }
    done();
  } catch (err) {
    done(err);
  }
}

