/**
 * Seat responses that mean "this seat did not answer": login walls, browser
 * timeouts and M365 filler. These must never be treated as a review.
 */
isUnusableResponse(text) {
  if (typeof text !== 'string') return true;
  if (/login required|awaiting user login|waiting for user login|login may have expired/i.test(text)) return true;
  if (/response timed out|no send control|could not type into the composer/i.test(text)) return true;
  if (/not selectable/i.test(text)) return true;
  return /^(getting things ready|in progress|thinking\.\.\.|please wait|working( on it)?|just a moment|hold on|one moment|looking into it|let me|i wasn't able to generate)/i.test(text.trim()) ||
         /send a new prompt or start a new chat/i.test(text);
}

/** Wrap a seat answer: unusable text becomes a failed seat, never a response. */
normalizeSeatAnswer(model, text) {
  if (this.isUnusableResponse(text)) {
    return { model, response: `[Seat unavailable: ${model}] ${text}`, phase: 'failed', error: true };
  }
  return { model, response: text };
}

