async dismissPopups(client, options = {}) {
  const attempts = Number.isFinite(options.attempts) ? options.attempts : this.popupRecoveryAttempts;
  const waitMs = Number.isFinite(options.waitMs) ? options.waitMs : 150;
  const result = { detected: false, handled: false, unresolved: false, actions: [] };
  for (let attempt = 0; attempt < attempts; attempt++) {
    let state;
    try {
      state = await client.evaluate(popupDiscoveryExpression());
    } catch (err) {
      result.unresolved = true;
      console.error(`[WebChatBrowser] popup discovery failed: ${err.message}`);
      break;
    }
    if (!state || !state.detected) {
      result.handled = true;
      break;
    }
    result.detected = true;
    const action = state.action || 'escape';
    result.actions.push(action);
    if (state.selector) {
      let clicked = false;
      try {
        clicked = await client.realClick(state.selector);
      } catch (err) {
        clicked = false;
      }
      if (!clicked) {
        try {
          await client.evaluate(popupClickExpression());
        } catch (err) {
          console.error(`[WebChatBrowser] popup click failed: ${err.message}`);
        }
      }
      try {
        await client.evaluate(popupClearExpression());
      } catch (err) {}
    } else {
      try {
        await client.evaluate(popupEscapeExpression());
      } catch (err) {
        console.error(`[WebChatBrowser] popup escape failed: ${err.message}`);
      }
    }
    if (attempt + 1 < attempts) await this.sleep(waitMs);
  }
  if (result.detected && result.actions.length >= attempts) result.unresolved = true;
  return result;
}

