async def _run_opencode_model(
    prompt: str, model: str, session_id: Optional[str] = None
) -> OpenCodeResult:
    if not OPENCODE_BIN.exists():
        raise FileNotFoundError(f"opencode not found at {OPENCODE_BIN}")

    WORKDIR.mkdir(parents=True, exist_ok=True)
    command = _build_opencode_command(prompt, model, session_id)
    logger.info(
        "Running OpenCode model=%s continuing=%s", model, bool(session_id)
    )
    process = await asyncio.create_subprocess_exec(
        *command,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    )
    try:
        stdout, stderr = await asyncio.wait_for(
            process.communicate(), timeout=TIMEOUT
        )
    except asyncio.TimeoutError:
        process.kill()
        await process.wait()
        raise TimeoutError(f"opencode did not finish within {TIMEOUT}s")

    raw_stdout = stdout.decode("utf-8", errors="replace")
    raw_stderr = stderr.decode("utf-8", errors="replace")
    result = _parse_opencode_events(raw_stdout)
    if process.returncode != 0:
        summary = _strip_ansi(raw_stderr or raw_stdout).strip().replace("\n", " ")
        raise RuntimeError(
            f"OpenCode exited with {process.returncode}: {summary[:300]}"
        )
    if not result.text:
        raise RuntimeError("OpenCode returned no assistant text")
    return result


async def _run_opencode(
    prompt: str, session_id: Optional[str] = None
) -> OpenCodeResult:
    models = list(dict.fromkeys(model for model in (MODEL, FALLBACK_MODEL) if model))
    for model in models:
        try:
            return await _run_opencode_model(prompt, model, session_id)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            logger.warning("OpenCode model=%s failed: %s", model, type(exc).__name__)
    raise OpenCodeUnavailableError(
        "OpenCode is temporarily unavailable. Please try again."
    )

