async generateImplementationPlan(problem, context, rounds, models = [], labels = null) {
  console.error('[Council] Generating implementation plan...');

  // Compile all discussion into a summary. With anonymization on, the
  // chairman reads the same anonymous transcript the reviewers saw: a
  // chairman that sees identities while synthesizing keeps the self-
  // preference bias that anonymizing only the critique stage would leave open.
  const discussionSummary = rounds.map(r => {
    const body = labels
      ? ledger.anonymizePeerResponses(r.responses, labels)
      : r.responses.map(res => `[${res.model}]: ${String(res.response).substring(0, 1500)}`).join('\n\n');
    return `Round ${r.round} (${r.phase}):\n${body}`;
  }).join('\n\n==========\n\n');

