def effective_benchmark(model: dict | None) -> tuple:
    """The one number used for ordering, as (benchmark_key, value).

    DeepSWE wins when present, because it is the benchmark the whole catalog
    was built around and the only one with an official board. Otherwise the
    model has exactly one unofficial benchmark recorded (the common case), and
    that is returned with its benchmark name attached so no caller can ever
    compare it to a DeepSWE number without saying which it is.
    """
    fields = benchmark_fields_of(model)
    if not fields:
        return None, None
    if DEEPSWE_BENCHMARK in fields:
        return DEEPSWE_BENCHMARK, fields[DEEPSWE_BENCHMARK]
    if len(fields) == 1:
        return next(iter(fields))
    # More than one non-DeepSWE benchmark: no principled way to pick, so
    # UNSCORED for ordering rather than an arbitrary maximum.
    return None, None


def benchmark_provenance_ok(model: dict | None, bench_key: str, value) -> bool:
    """Can a reader audit where this number came from?

    For an unofficial number that means: the benchmark is named, a source URL
    is recorded, the number is marked verified, and the stored snippet actually
    CONTAINS the number. The last clause is what stops a provenance record that
    is technically present but describes something else.

    For the official DeepSWE number the evidence has always lived in flat fields
    (board source url + board version + the verbatim board line), and all three
    must be present with the number inside the line.
    """
    val = _num(value)
    if val is None:
        return False
    tier = str((model or {}).get("score_tier") or "").strip().lower()
    if tier == "official" and bench_key == DEEPSWE_BENCHMARK:
        return bool(
            score_source_of(model) == "deepswe-board"
            and (model or {}).get("score_source_url")
            and (model or {}).get("score_board_version")
            and score_appears_in_snippet(val, (model or {}).get("score_verbatim") or ""))
    prov = ((model or {}).get("bench_provenance") or {}).get(bench_key) or {}
    if not isinstance(prov, dict) or not prov:
        return False
    if str((model or {}).get("score_benchmark") or "") != bench_key:
        return False, "a field whose benchmark is not named is not provenance"
    if not prov.get("url") or prov.get("verified") is not True:
        return False
    if not score_appears_in_snippet(val, prov.get("snippet") or ""):
        return False
    if not plausible_benchmark_score(bench_key, val):
        return False
    return True

